{
  "public_post": "Reminder: Do NOT purchase any co-op bread today. We are recalling all bread due to a contaminated flour batch. Please get your bread from the farm stand and contact us for refunds.",
  "coop_message": "All members: We must immediately recall any bread already distributed, process refunds for affected residents, and arrange a meeting at 3 PM to decide on compensation and next steps. Please confirm who has reported illness.",
  "reason": "To protect villagers' health, coordinate a recall and refunds, and plan next actions."
}

{
  "public_post": "Update: All contaminated bread has been recalled and refunds will be issued to anyone who bought it this week. Please continue using the farm stand for your bread until we can provide safe supply.",
  "coop_message": "All members: Let's arrange refunds for any sales made, coordinate with the clinic to help affected residents, and source a new safe flour batch; meet today at 3 PM to finalize the plan.",
  "reason": "To maintain villagers' trust while organizing refunds and a safe replacement for the co-op."
}

{
  "public_post": "Reminder: Do NOT purchase co-op bread today; refunds are being processed for anyone who bought contaminated loaves, and we advise anyone feeling ill to visit the clinic.",
  "coop_message": "All members: Please finalize refunds for all affected residents today, confirm the number of illness reports, and update on sourcing a safe flour batch; meeting at 4 PM to discuss compensation.",
  "reason": "We need to keep villagers safe and maintain trust while coordinating refunds and a new flour supply."
}

{
  "public_post": "Good news, villagers! Our new safe flour batch arrived overnight and fresh, healthy loaves are back on the board today. All refunds have been processed—come by for your bread!",
  "coop_message": "All members: New flour is in, start baking immediately; follow strict hygiene, track inventory, and coordinate deliveries for today’s sales.",
  "reason": "To announce the safe return of bread and restart sales after the contamination issue."
}

{
  "public_post": "Apology: Our flour was contaminated earlier this week, causing several illnesses. All affected loaves have been recalled, refunds issued, and the contaminated stock destroyed. Safe flour is now in use and fresh loaves are available today at the usual price. Thank you for your patience and trust.",
  "coop_message": "Team, let's offer a 20% discount on today's loaves and a free loaf to any resident who reported illness to rebuild trust; confirm inventory, apply the discount, and post a brief statement confirming refunds and safety measures on the board.",
  "reason": "Transparency about the contamination restores trust while a discount encourages villagers to resume buying from the co‑op."
}

{
  "public_post": "Good news, villagers! Our bread is safe and back on the board today. To thank you for your patience, all loaves are 20% off and anyone who fell ill receives a free loaf—please stop by the co‑op.",
  "coop_message": "Team, confirm we have enough safe inventory for today’s 15 loaves, apply the 20% discount and free‑loaf vouchers, and log sales; also start planning a weekly safety audit to prevent future issues.",
  "reason": "To restore trust, boost sales, and ensure safe operations after the contamination incident."
}

{
  "public_post": "Good morning, villagers! Our safe flour batch is in use and fresh loaves are ready. Today each loaf is only 0.9 coin, and anyone who fell ill this week can claim a free loaf. If you’re still feeling unwell, please visit the clinic. Thank you for your patience!",
  "coop_message": "All 15 loaves baked and ready; apply the 0.9 coin price and issue free‑loaf vouchers to residents who reported illness; continue monitoring clinic reports and be prepared for any last‑minute refunds; no further contaminated stock remains.",
  "reason": "To rebuild trust and maximize sales after the contamination incident."
}
